-- শুধু SELECT, কিছু বদলায় না -- কিশানগঞ্জ নন-বিলড ব্যাচের patientId সিরিয়াল যাচাই (batch 1/2)
select
  substring("patientId" from 5 for 8) as date_part,
  max(substring("patientId" from 14)::int) as max_serial_used
from public.patients
where "patientId" ~ '^KNE-\d{8}-\d+$'
  and substring("patientId" from 5 for 8) in ('07062024', '04012025', '06012025', '10012025', '11012025', '13012025', '14012025', '15012025', '16012025', '18012025', '20012025', '22012025', '23012025', '25012025', '28012025', '29012025', '31012025', '03022025', '05022025', '06022025', '07022025', '12022025', '13022025', '14022025', '15022025', '17022025', '19022025', '20022025', '26022025', '27022025', '28022025', '01032025', '03032025', '06032025', '10032025', '12032025', '13032025', '17032025', '19032025', '20032025', '24032025', '25032025', '26032025', '29032025', '30032025', '02042025', '04042025', '07042025', '08042025', '10042025', '11042025', '16042025', '18042025', '19042025', '21042025', '22042025', '24042025', '26042025', '28042025', '29042025', '01052025', '02052025', '03052025', '05052025', '06052025', '07052025', '08052025', '10052025', '13052025', '15052025', '16052025', '17052025', '18052025', '19052025', '22052025', '24052025', '26052025', '27052025', '28052025', '03062025', '04062025', '05062025', '07062025', '10062025', '11062025', '13062025', '16062025', '18062025', '19062025', '21062025', '24062025', '26062025', '27062025', '28062025', '29062025', '02072025', '03072025')
group by date_part
order by date_part;
